import{t as e}from"./LegalLayout--Yury8xU.js";import{o as t}from"./useSelector-DVnrlu_j.js";var n=t();function r(){return(0,n.jsx)(e,{title:`Allgemeine Geschäftsbedingungen`,intro:`Diese AGB regeln die Vertragsbeziehung zwischen der OSCW Office Service & Co. Working GmbH (nachfolgend „Sekretariat-Service") und ihren Kundinnen und Kunden.`,sections:[{id:`geltung`,title:`§ 1 Geltungsbereich`,content:(0,n.jsx)(`p`,{children:`Diese Allgemeinen Geschäftsbedingungen (AGB) gelten für sämtliche Verträge über Leistungen der OSCW Office Service & Co. Working GmbH, Hugo-Heimann-Str. 37, 12353 Berlin, im Rahmen des Angebots Sekretariat-Service. Abweichende Bedingungen des Kunden erkennen wir nicht an, es sei denn, wir stimmen ihrer Geltung ausdrücklich schriftlich zu.`})},{id:`leistungen`,title:`§ 2 Leistungen`,content:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`p`,{children:`Sekretariat-Service bietet einen professionellen Telefonservice für Unternehmen. Dies umfasst insbesondere Anrufannahme im Namen des Kunden, Notieren und Weiterleiten von Nachrichten, Terminvereinbarungen, einfache Auskünfte gemäß vorgegebenem Gesprächsleitfaden sowie optionale Zusatzleistungen (z.\xA0B. mehrsprachige Betreuung).`}),(0,n.jsx)(`p`,{children:`Der genaue Leistungsumfang ergibt sich aus dem individuell gewählten Tarif und den ergänzenden Absprachen im Onboarding.`})]})},{id:`vertragsschluss`,title:`§ 3 Vertragsschluss & Testphase`,content:(0,n.jsx)(`p`,{children:`Der Vertrag kommt durch Bestätigung der Beauftragung durch Sekretariat-Service zustande. Sofern ein kostenfreier Testzeitraum vereinbart wird, endet dieser automatisch ohne gesonderte Kündigung; ein Übergang in ein kostenpflichtiges Abonnement erfolgt nur, wenn der Kunde diesen ausdrücklich beauftragt.`})},{id:`laufzeit`,title:`§ 4 Laufzeit & Kündigung`,content:(0,n.jsx)(`p`,{children:`Verträge werden – sofern nicht abweichend vereinbart – monatlich abgeschlossen und verlängern sich automatisch um jeweils einen Monat, sofern sie nicht mit einer Frist von 14 Tagen zum Laufzeitende in Textform gekündigt werden. Das Recht zur außerordentlichen Kündigung aus wichtigem Grund bleibt unberührt.`})},{id:`preise`,title:`§ 5 Preise & Zahlung`,content:(0,n.jsx)(`p`,{children:`Es gelten die zum Zeitpunkt der Beauftragung gültigen Preise gemäß Preisliste bzw. individuellem Angebot. Alle Preise verstehen sich zzgl. der gesetzlichen Umsatzsteuer. Die Abrechnung erfolgt monatlich per SEPA-Lastschrift oder Überweisung. Rechnungen sind ohne Abzug innerhalb von 14 Tagen nach Zugang fällig.`})},{id:`pflichten`,title:`§ 6 Pflichten des Kunden`,content:(0,n.jsx)(`p`,{children:`Der Kunde stellt Sekretariat-Service alle für die Leistungserbringung erforderlichen Informationen rechtzeitig und vollständig zur Verfügung. Er sorgt insbesondere für die technisch korrekte Rufumleitung und stellt sicher, dass er berechtigt ist, die angegebenen Rufnummern für den Telefonservice zu nutzen.`})},{id:`verfuegbarkeit`,title:`§ 7 Verfügbarkeit`,content:(0,n.jsx)(`p`,{children:`Sekretariat-Service ist bemüht, den Dienst 24/7 verfügbar zu halten. Kurzfristige Einschränkungen aufgrund technischer Wartungen, Störungen von Vorleistungen (z.\xA0B. Netzbetreiber) oder höherer Gewalt bleiben vorbehalten.`})},{id:`haftung`,title:`§ 8 Haftung`,content:(0,n.jsx)(`p`,{children:`Sekretariat-Service haftet unbeschränkt für Vorsatz und grobe Fahrlässigkeit sowie für Schäden aus der Verletzung des Lebens, des Körpers oder der Gesundheit. Bei leichter Fahrlässigkeit haften wir nur bei Verletzung wesentlicher Vertragspflichten (Kardinalpflichten) und begrenzt auf den vertragstypisch vorhersehbaren Schaden. Eine weitergehende Haftung ist ausgeschlossen.`})},{id:`datenschutz`,title:`§ 9 Datenschutz`,content:(0,n.jsx)(`p`,{children:`Beide Parteien verpflichten sich zur Einhaltung der anwendbaren datenschutzrechtlichen Vorschriften. Erforderlich- enfalls schließen die Parteien einen Vertrag zur Auftragsverarbeitung nach Art. 28 DSGVO. Details zur Datenverarbeitung enthält unsere Datenschutzerklärung.`})},{id:`schluss`,title:`§ 10 Schlussbestimmungen`,content:(0,n.jsx)(`p`,{children:`Es gilt das Recht der Bundesrepublik Deutschland unter Ausschluss des UN-Kaufrechts. Ausschließlicher Gerichtsstand für alle Streitigkeiten mit Kaufleuten, juristischen Personen des öffentlichen Rechts oder öffentlich-rechtlichen Sonder- vermögen ist Berlin. Sollten einzelne Bestimmungen unwirksam sein, bleibt die Wirksamkeit der übrigen Bestimmungen unberührt.`})}]})}export{r as component};